if self.session.props.auth.authenticated:
	system.perspective.logout()
else:
	system.perspective.login()

# Dev only (epic 3 entry 5): Pressure of P12 to 400 (below the alarm setpoint), through the project library mapstudio_live, so the
# e2e suite and the owner can see an icon and its popup follow. Dev tags only; MapEditor only.
import java.lang

logger = system.util.getLogger('MapStudio.devlive')
out = self.view.rootContainer.getChild('liveResult')
if not mapstudio_dev.holdsMapEditor(self.session):
	out.props.text = system.util.jsonEncode({'refused': 'The live buttons write dev tags, so they need the MapEditor role. Sign in as a map editor first.', 'ranAt': system.date.toMillis(system.date.now())})
	return
try:
	result = mapstudio_live.set_pressure('P12', 400)
	result['status'] = mapstudio_live.status('P12')
except java.lang.Throwable as ex:
	result = {'error': ex.getClass().getSimpleName() + ': ' + str(ex.getMessage())}
except Exception as ex:
	result = {'error': str(ex)}
result['action'] = 'pressure-low'
result['ranAt'] = system.date.toMillis(system.date.now())
out.props.text = system.util.jsonEncode(result)

